import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";

function DashboardProf() {
  const navigate = useNavigate();
  const [user, setUser] = useState(null);

  useEffect(() => {
    // Récupérer les infos utilisateur depuis localStorage (table users)
    const userData = localStorage.getItem('user');
    const isAuthenticated = localStorage.getItem('isAuthenticated');
    
    if (!isAuthenticated || !userData) {
      navigate("/login");
      return;
    }

    const userObj = JSON.parse(userData);
    
    // Vérifier que c'est bien un professeur depuis la table users
    if (userObj.role !== "prof") {
      alert("❌ Accès réservé aux professeurs");
      navigate("/login");
      return;
    }

    setUser(userObj);
    console.log('👨‍🏫 Données professeur depuis la table users:', userObj);
  }, [navigate]);

  const handleLogout = () => {
    localStorage.removeItem('user');
    localStorage.removeItem('isAuthenticated');
    localStorage.removeItem('userRole');
    localStorage.removeItem('token');
    navigate("/login");
  };

  if (!user) {
    return (
      <div className="loading-container">
        <div className="spinner"></div>
        <p>Chargement des données professeur...</p>
      </div>
    );
  }

  return (
    <div className="dashboard-prof">
      <header className="dashboard-header">
        <div className="header-content">
          <h1>Tableau de Bord Professeur</h1>
          <div className="user-info">
            <span>Bienvenue, <strong>{user.nom}</strong></span>
            <div className="user-role">
              <span className="role-badge prof">PROFESSEUR</span>
              <button onClick={handleLogout} className="btn btn-secondary">
                Déconnexion
              </button>
            </div>
          </div>
        </div>
      </header>

      <main className="dashboard-main">
        <div className="welcome-section">
          <h2>Bonjour, Professeur {user.nom} 👨‍🏫</h2>
          <div className="user-details">
            <div className="info-card">
              <h3>Informations depuis la table users</h3>
              <p><strong>ID:</strong> {user.id}</p>
              <p><strong>Email:</strong> {user.email}</p>
              <p><strong>Rôle:</strong> {user.role}</p>
              <p><strong>Matière:</strong> {user.matiere || 'Non spécifiée'}</p>
              <p><strong>Spécialité:</strong> {user.specialite || 'Non spécifiée'}</p>
            </div>
          </div>
        </div>

        <div className="dashboard-grid">
          <div className="dashboard-card">
            <h3>Mes Cours</h3>
            <p>Gérer vos cours et emploi du temps</p>
            <button className="btn btn-primary">Voir mes cours</button>
          </div>

          <div className="dashboard-card">
            <h3>Étudiants</h3>
            <p>Consulter la liste de vos étudiants</p>
            <button className="btn btn-primary">Voir les étudiants</button>
          </div>

          <div className="dashboard-card">
            <h3>Notes</h3>
            <p>Gérer les notes et évaluations</p>
            <button className="btn btn-primary">Gérer les notes</button>
          </div>

          <div className="dashboard-card">
            <h3>Rapports</h3>
            <p>Consulter les rapports et statistiques</p>
            <button className="btn btn-primary">Voir les rapports</button>
          </div>
        </div>
      </main>
    </div>
  );
}

export default DashboardProf;
